{
  "word": "glimmer",
  "lang": "en",
  "phonetic": "/ˈɡlɪmə(ɹ)/",
  "meanings": [
    {
      "pos": "noun",
      "senses": [
        {
          "definition": "A faint light; a dim glow.",
          "example": "The glimmer of the fireflies was pleasant to watch."
        },
        {
          "definition": "A flash of light."
        },
        {
          "definition": "A faint or remote possibility.",
          "example": "A glimmer of hope."
        }
      ]
    },
    {
      "pos": "verb",
      "senses": [
        {
          "definition": "To shine with a faint, unsteady light.",
          "example": "The fireflies glimmered in the dark."
        }
      ]
    }
  ],
